# RW4DM_CPSEL: InvertPt and ShowPt: the selection of control points. The scripts are rw4dm_cpsel_invert_script.txt, rw4dm_cpsel_twice_script.txt, rw4dm_cpsel_showpt_script.txt; generated by rw4dm_gen.py (the closed forms are in that file). Every object kind of the case (Point, Line, Plane, Box) is
# compared with the closed-form image of the operation: points by the residual move to the origin (printed 0,0,0 within 1e-9), curve / surface control points
# through ExtractPt the same way, boxes by their bounding box after a residual move. RW4DM_CPSEL_sensitivity shows that a 1e-6 error would read 1e-06.
RW4_CPSEL_OUT=""
rw4_cpsel_run() {
  local o
  if [ -n "${DISPLAY:-}" ] && xset q >/dev/null 2>&1 || ! command -v xvfb-run >/dev/null 2>&1; then
    o="$(timeout 900 "$BIN" --smoke 60 --script "$HERE/$1" 2>&1)" || { echo "$o" | tail -40; echo "FAIL RW4DM_CPSEL_run: $1 exited non-zero"; fail=1; o=""; }
  else
    o="$(timeout 900 xvfb-run -a -s "-screen 0 1600x900x24" "$BIN" --smoke 60 --script "$HERE/$1" 2>&1)" || { echo "$o" | tail -40; echo "FAIL RW4DM_CPSEL_run: $1 exited non-zero"; fail=1; o=""; }
  fi
  RW4_CPSEL_OUT+="$o"$'\n'
}
rw4_cpsel_run rw4dm_cpsel_invert_script.txt
rw4_cpsel_run rw4dm_cpsel_twice_script.txt
rw4_cpsel_run rw4dm_cpsel_showpt_script.txt
rw4_cpsel_block() { awk -v name="$1" '$0 ~ ("Unknown command: RW4BEGIN_" name "$") { on = 1; next } on && /Unknown command: RW4BEGIN_/ { exit } on { print }' <<<"$RW4_CPSEL_OUT"; }
# rw4_cpsel_resid NAME NPTS BOXES DESC: the case listed exactly NPTS points, every one at residual 0,0,0, and the boxes' bounding boxes (joined by ';') read exactly BOXES
rw4_cpsel_resid() {
  local blk npts zeros boxes; blk="$(rw4_cpsel_block "$1")"
  npts="$({ grep -cE '^history: Object [0-9]+ \(point\)' <<<"$blk" || true; })"
  zeros="$({ grep -cE '^history:   0,0,0$' <<<"$blk" || true; })"
  boxes="$({ grep -E '^history: Bounding box min ' <<<"$blk" || true; } | sed -E 's/^history: Bounding box //' | paste -sd';' -)"
  if [ "$npts" = "$2" ] && [ "$zeros" = "$2" ] && [ "$boxes" = "$3" ]; then echo "ok   RW4DM_CPSEL_$1: $4 ($2 points at residual 0 within 1e-9; boxes: ${3:-none})"
  else echo "FAIL RW4DM_CPSEL_$1: $4 (listed $npts points, $zeros at residual 0, expected $2 and $2; boxes '$boxes', expected '$3')"; fail=1; { grep -E '^history:   |^history: Bounding box|^history: ! ' <<<"$blk" || true; } | head -16 | sed 's/^/     residual: /'; fi
}
rw4_cpsel_resid invert 6 "" "InvertPt after SelControlPointRegion picked 3 of the 6 control points selects exactly the other 3: SetPt Z=5 lifts those (line CV1, plane CV1 and CV3) and nothing else"
rw4_cpsel_resid twice 6 "" "InvertPt twice is the identity: the second inversion selects the original 3 control points again, SetPt Z=9 lifts those, the first 3 stay at 5"
rw4_cpsel_resid showpt 6 "" "ShowPt turns the control points of the selected objects back on: after PointsOff the region selects nothing, after ShowPt it selects the 3 control points that SetPt Z=4 then lifts"
# negative control: the same harness must SEE a 1e-6 error (a point 1e-6 off its expected image reads 1e-06, not 0)
rw4_cpsel_sens() {
  local blk; blk="$(rw4_cpsel_block sensitivity)"
  if grep -qE '^history:   (0,0,)?[-0-9.e]*1e-06' <<<"$blk" && ! grep -qE '^history:   0,0,0$' <<<"$blk"; then echo "ok   RW4DM_CPSEL_sensitivity: the residual harness reports a 1e-6 error as 1e-06 (negative control)"
  else echo "FAIL RW4DM_CPSEL_sensitivity: a 1e-6 error was not visible"; fail=1; { grep -E '^history:   ' <<<"$blk" || true; } | head -4 | sed 's/^/     residual: /'; fi
}
rw4_cpsel_sens
